-- SELECT only. Save before apply. System catalogs and the migration history only (no app table rows).
-- 바뀌는 것 전부의 되돌릴 기준: 통화·텔레그램 표 12개의 RLS·표 권한·정책·트리거(이 migration은 표마다 정책 하나·트리거 하나만 더함), 새 표·새 함수(적용 전엔 없음), 기록.
select 'function' as kind,p.oid::regprocedure::text as name,p.prosecdef::text||':'||coalesce(p.proconfig::text,'none')||':'||coalesce(p.proacl::text,'none')||':'||md5(p.prosrc) as definition
  from pg_proc p where p.oid in(to_regprocedure('private.app_workspace_has_feature(uuid,text)'),to_regprocedure('public.app_my_features()'),to_regprocedure('public.app_operator_feature_workspace(text)'),to_regprocedure('private.app_operator_feature_guard()'),to_regprocedure('private.app_is_workspace_owner(uuid)'))
union all select 'trigger',c.relname::text||'.'||t.tgname::text,t.tgenabled::text||':'||pg_get_triggerdef(t.oid) from pg_trigger t join pg_class c on c.oid=t.tgrelid where t.tgrelid in(to_regclass('public.app_feed_items'),to_regclass('public.app_feed_days'),to_regclass('public.app_call_personal'),to_regclass('public.app_call_edits'),to_regclass('public.app_call_edit_history'),to_regclass('public.app_tg_senders'),to_regclass('public.app_tg_day_senders'),to_regclass('public.app_feed_folders'),to_regclass('public.app_feed_rooms'),to_regclass('public.app_feed_room_days'),to_regclass('public.app_feed_summary_edits'),to_regclass('public.app_feed_summary_edit_history'),to_regclass('public.app_operator_features')) and not t.tgisinternal
union all select 'table',c.relname::text,c.relrowsecurity::text||':'||c.relforcerowsecurity::text||':'||coalesce(c.relacl::text,'none') from pg_class c where c.oid in(to_regclass('public.app_feed_items'),to_regclass('public.app_feed_days'),to_regclass('public.app_call_personal'),to_regclass('public.app_call_edits'),to_regclass('public.app_call_edit_history'),to_regclass('public.app_tg_senders'),to_regclass('public.app_tg_day_senders'),to_regclass('public.app_feed_folders'),to_regclass('public.app_feed_rooms'),to_regclass('public.app_feed_room_days'),to_regclass('public.app_feed_summary_edits'),to_regclass('public.app_feed_summary_edit_history'),to_regclass('public.app_operator_features'))
union all select 'policy',c.relname::text||'.'||p.polname::text,p.polcmd::text||':'||p.polpermissive::text||':'||p.polroles::text||':'||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||':'||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),'') from pg_policy p join pg_class c on c.oid=p.polrelid where p.polrelid in(to_regclass('public.app_feed_items'),to_regclass('public.app_feed_days'),to_regclass('public.app_call_personal'),to_regclass('public.app_call_edits'),to_regclass('public.app_call_edit_history'),to_regclass('public.app_tg_senders'),to_regclass('public.app_tg_day_senders'),to_regclass('public.app_feed_folders'),to_regclass('public.app_feed_rooms'),to_regclass('public.app_feed_room_days'),to_regclass('public.app_feed_summary_edits'),to_regclass('public.app_feed_summary_edit_history'),to_regclass('public.app_operator_features'))
union all select 'history',version,name from supabase_migrations.schema_migrations where version in('20261027200000','20261028030000','20261029090000')
order by 1,2;
